import{_ as a,o as e,c as i,a5 as t}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"RBQ Development PC 연결 방법","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/release-note/how-to-connect-rbq-dev-pc.md","filePath":"ko/software/release-note/how-to-connect-rbq-dev-pc.md","lastUpdated":1785806273000}'),n={name:"ko/software/release-note/how-to-connect-rbq-dev-pc.md"};function o(l,s,r,p,c,h){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="rbq-development-pc-연결-방법" tabindex="-1">RBQ Development PC 연결 방법 <a class="header-anchor" href="#rbq-development-pc-연결-방법" aria-label="Permalink to &quot;RBQ Development PC 연결 방법&quot;">​</a></h1><p>이 가이드는 원격 데스크톱 접속을 위해 <strong>NoMachine</strong>을 사용하여 <strong>RBQ Dev PC</strong>에 연결하는 방법을 설명합니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p><strong>RBQ Dev PC</strong>는 로봇에 탑재된 <strong>User-PC 모듈</strong>로, 사용자가 개발 작업을 수행하는 PC입니다. User-PC 모듈은 <strong>옵션</strong>이므로 로봇 구성에 따라 탑재되지 않을 수 있습니다.</p></div></div><h2 id="_1단계-nomachine-다운로드" tabindex="-1">1단계. NoMachine 다운로드 <a class="header-anchor" href="#_1단계-nomachine-다운로드" aria-label="Permalink to &quot;1단계. NoMachine 다운로드&quot;">​</a></h2><ol><li><p>공식 웹사이트에서 NoMachine 애플리케이션을 다운로드합니다: 🔗 <a href="https://www.nomachine.com/" target="_blank" rel="noreferrer">NoMachine 다운로드 페이지</a></p></li><li><p>플랫폼(Linux)에 맞는 올바른 버전을 선택하세요.</p></li></ol><h2 id="_2단계-rbq-dev-pc에-nomachine-설치" tabindex="-1">2단계. RBQ Dev PC에 NoMachine 설치 <a class="header-anchor" href="#_2단계-rbq-dev-pc에-nomachine-설치" aria-label="Permalink to &quot;2단계. RBQ Dev PC에 NoMachine 설치&quot;">​</a></h2><p>터미널을 열고 다음 명령어를 실행하여 NoMachine을 설치합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zxvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/nomachine_latest_version.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/NX/nxserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/NX/bin/nxserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span></span></code></pre></div><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p><code>nxserver --status</code>를 사용하여 서버가 정상적으로 실행 중인지 확인하세요.</p></div></div><h2 id="_3단계-개발-pc에서-연결" tabindex="-1">3단계. 개발 PC에서 연결 <a class="header-anchor" href="#_3단계-개발-pc에서-연결" aria-label="Permalink to &quot;3단계. 개발 PC에서 연결&quot;">​</a></h2><ol><li><p><strong>개발 PC가 RBQ와 동일한 네트워크에 연결</strong>되어 있는지 확인하세요 (이더넷 또는 SSH 연결 가능).</p></li><li><p>PC에서 <strong>NoMachine 앱</strong>을 실행합니다.</p></li><li><p><strong>&quot;Add&quot;</strong>를 클릭하여 새 연결을 생성합니다.</p></li><li><p>다음 정보를 입력합니다:</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name : rbq</span></span>
<span class="line"><span>Host : 192.168.0.13</span></span></code></pre></div><p>U-PC의 기본 주소는 <code>192.168.0.13</code>입니다. 연결되지 않을 경우 U-PC에 모니터를 연결하여 현재 IP를 확인해 주세요. 다른 주소를 사용 중이라면 <code>192.168.0.13</code>으로 고정하여 사용해 주시기 바랍니다.</p><p>그래도 연결이 되지 않는 경우 <a href="/RBQ/ko/manual/troubleshooting/error-reporting.html">문의 부탁드립니다</a>.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>권장 NoMachine 디스플레이 해상도 설정:</p><ul><li>✅ 활성화: <strong>&quot;Scale the remote desktop to fit the window&quot;</strong></li><li>🚫 비활성화: <strong>&quot;Resize the remote display&quot;</strong></li></ul></div></div><h2 id="연결-완료" tabindex="-1">연결 완료! <a class="header-anchor" href="#연결-완료" aria-label="Permalink to &quot;연결 완료!&quot;">​</a></h2><p>이제 사용자 친화적인 데스크톱 인터페이스를 통해 <strong>RBQ Dev PC</strong>를 원격으로 제어하고 개발할 수 있습니다.</p><p>개발 워크플로우를 즐기세요!</p>`,18)])])}const b=a(n,[["render",o]]);export{k as __pageData,b as default};
